<?php
namespace qqworld_collector\module\cloud_storage; use qqworld_collector\module\cloudStorage2; class image_hosting_api extends cloudStorage2 { public function init() { $this->host = $this->options->cloud_storage_image_hosting_api_host; $this->silent_scanning = $this->options->cloud_storage_image_hosting_api_silent_scanning; $this->delete_attachment_after_synced = $this->options->cloud_storage_joinmode_enabled ? 0 : $this->options->cloud_storage_image_hosting_api_delete_attachment_after_synced; } public function upload($destination_path, $source_path) { if (!file_exists($source_path) || !filesize($source_path)) return false; return apply_filters( 'qqworld-collector-cloud-storage-image-hosting-api', false, $source_path ); } public function add_could_storage_form($guid) { $this->accessed = $this->is_current; require QQWORLD_COLLECTOR_DIR . 'pages' . DIRECTORY_SEPARATOR . 'cloudStorage-'.$this->guid.'.php'; } } ?>